import yaml, re
with open('registry.yaml') as f:
    data = yaml.safe_load(f)
exps = data.get('experiments', {})
# The catastrophic result comes from lr5e6_r1. Find the training experiment
for exp_id in ['mvp2_grpo_ced_lr5e6_rp_r1', 'mvp2_grpo_lr5e6_r1', 'mvp2_grpo_ced_lr5e6']:
    exp = exps.get(exp_id, {})
    if exp:
        spec = exp.get('spec', {}) or {}
        cmd = spec.get('command', '')
        reproduce = exp.get('reproduce', {}) or {}
        rcmd = reproduce.get('command', '')
        full_cmd = cmd or rcmd
        lr = re.search(r'--learning_rate\s+(\S+)', full_cmd)
        batch = re.search(r'--per_device_batch_size\s+(\d+)', full_cmd)
        ga = re.search(r'--gradient_accumulation_steps\s+(\d+)', full_cmd)
